from bisect import bisect_left, bisect_right
import math

class TrieNode:
    def __init__(self):
        self.children = {}
        self.price = 0

class Solution:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, house, price):
        node = self.root
        for i, h in enumerate(house):
            if h not in node.children:
                node.children[h] = TrieNode()
            node = node.children[h]
        node.price = price

    def query(self, house):
        node = self.root
        total_price = 0
        for h in house:
            if h in node.children:
                if node.price!= 0:
                    total_price += node.price
                node = node.children[h]
            else:
                i = bisect_right(node.children.keys(), h)
                if i > 0:
                    total_price += node.children[list(node.children.keys())[i-1]].price
                return total_price
        return total_price

    def maxProfit(self, houses, offers):
        """
        This function calculates the maximum possible profit by assigning houses to buyers.

        Parameters:
